import React from 'react';

const ResumePreview = ({ resumeData, onDownload }) => {
  if (!resumeData) return null;

  return (
    <div className="bg-white rounded-lg shadow-md p-6">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-semibold">Your Resume Preview</h2>
        <button
          onClick={onDownload}
          className="bg-green-600 text-white px-4 py-2 rounded-lg hover:bg-green-700 transition-colors"
        >
          Download DOCX
        </button>
      </div>
      <div className="prose max-w-none">
        <h1 className="text-3xl font-bold mb-2">{resumeData.name}</h1>
        <p className="text-xl text-gray-600 mb-4">{resumeData.title}</p>
        
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
          <div>
            <p className="text-gray-600">{resumeData.email}</p>
            <p className="text-gray-600">{resumeData.phone}</p>
          </div>
          <div>
            <p className="text-gray-600">{resumeData.location}</p>
          </div>
        </div>

        {resumeData.sections?.map((section, index) => (
          <div key={index} className="mb-6">
            <h2 className="text-2xl font-semibold border-b-2 border-gray-200 pb-2 mb-4">
              {section.title}
            </h2>
            {section.content && <div dangerouslySetInnerHTML={{ __html: section.content }} />}
          </div>
        ))}
      </div>
    </div>
  );
};

export default ResumePreview;
